#include <iostream>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    int64 low = 0, high = 1;

    auto sufficient = [n](int64 k) {
        i128 i = static_cast<i128>(2) * k + 1;
        return i * (i + 1) / 2 >= n;
    };

    while (!sufficient(high)) {
        high *= 2;
    }

    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (sufficient(mid))
            high = mid;
        else
            low = mid + 1;
    }

    cout << 2 * low + 1;
    return 0;
}

