int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    for (long long i = 1;; i += 2) {
        if ((__int128)i * (i + 1) / 2 >= n) {
            cout << i;
            break;
        }
    }

    return 0;
}

